The checkers work on toy strings. Now I'll write instruction phrasings of my own for every target type (several per type, so I don't tune to one wording) and assemble the 512-prompt diagnostic set: one instruction per prompt for most of them, plus 64 two-instruction combinations. Prompts and metadata go to /work so they survive a restart. Each prompt has a fresh task from the pool, and I keep a reserved part of the pool for later confirmation sets.

```python
# Hypothesis: none; build the diagnostic prompt set P1 (choice set) with instruction metadata.
R = random.Random(7)
kw_words = ['light','time','future','simple','change','journey','quiet','bright','balance','energy','home','memory','growth','open','trust','wonder']
def inst_text(inst, rng):
    k = inst['type']; N = inst.get('N'); rel = inst.get('rel')
    if k == 'lowercase': return rng.choice(["Your entire response should be in English and in lowercase letters only; capital letters are not allowed anywhere.",
        "Write your whole answer in lowercase letters only, without using a single capital letter.",
        "Make sure every letter in your reply is lowercase. No uppercase letters at all.",
        "Use only lowercase letters throughout your entire response."])
    if k == 'capital': return rng.choice(["Your entire response must be in English and written in capital letters only.",
        "Write the whole reply in uppercase letters; lowercase letters are not allowed.", "Respond using only CAPITAL letters from start to finish."])
    if k == 'no_comma': return rng.choice(["Do not use any commas in your response.", "Your answer must not contain a single comma.",
        "Avoid commas completely: none may appear anywhere in your reply.", "Write without using the comma character anywhere in the response."])
    if k == 'capword':
        if rel == 'at least': return rng.choice([f"In your response, words written in all capital letters should appear at least {N} times.",
            f"Use fully capitalized words (like THIS) at least {N} times in your answer."])
        return rng.choice([f"In your response, words written in all capital letters should appear fewer than {N} times.",
            f"Include fewer than {N} words that are written entirely in capital letters."])
    if k == 'words':
        if rel == 'at least': return rng.choice([f"Your response should contain at least {N} words.", f"Write at least {N} words."])
        return rng.choice([f"Answer with fewer than {N} words.", f"Keep your response under {N} words."])
    if k == 'sentences':
        if rel == 'at least': return rng.choice([f"Your response should contain at least {N} sentences.", f"Write at least {N} sentences."])
        return rng.choice([f"Your response should contain fewer than {N} sentences.", f"Use fewer than {N} sentences in total."])
    if k == 'paragraphs': return rng.choice([f"Your response should have exactly {N} paragraphs, separated from each other by the markdown divider ***.",
        f"Write exactly {N} paragraphs. Separate the paragraphs with the markdown divider ***."])
    if k == 'repeat': return rng.choice(["First repeat the request above word for word without any change, then give your answer. Do not write anything before the repeated request, and do not include this sentence in the repetition.",
        "Begin your reply by copying the request exactly as written (not including this sentence), and only then answer it. Nothing may come before the copied request."])
    if k == 'keyword': return rng.choice([f"Make sure the word '{inst['kw']}' appears at least {N} times in your response.", f"Include the keyword {inst['kw']} at least {N} times."])
    if k == 'highlight': return rng.choice([f"Highlight at least {N} sections of your answer with markdown, for example *highlighted section*.",
        f"Use markdown to italicize at least {N} key phrases, like *this one*."])
    if k == 'letter':
        if rel == 'at least': return f"In your response, the letter '{inst['letter']}' should appear at least {N} times."
        return f"Make sure the letter '{inst['letter']}' appears fewer than {N} times in your answer."
def rand_inst(k, rng, task):
    d = {'type': k}
    if k == 'capword': d['rel'] = rng.choice(['at least','less than']); d['N'] = rng.choice([3,5,8,10,15]) if d['rel']=='at least' else rng.choice([2,3,4,5,8])
    if k == 'words': d['rel'] = rng.choice(['at least','less than']); d['N'] = rng.choice([150,200,300,400,500]) if d['rel']=='at least' else rng.choice([40,60,80,100,150])
    if k == 'sentences': d['rel'] = rng.choice(['at least','less than']); d['N'] = rng.choice([8,10,15,20]) if d['rel']=='at least' else rng.choice([3,4,5,6,8])
    if k == 'paragraphs': d['N'] = rng.choice([2,3,4,5,6])
    if k == 'repeat': d['req'] = task
    if k == 'keyword': d['kw'] = rng.choice(kw_words); d['rel'] = 'at least'; d['N'] = rng.choice([2,3,4,5])
    if k == 'highlight': d['N'] = rng.choice([2,3,4,5,6])
    if k == 'letter': d['letter'] = rng.choice(list('bcdfgklmpqwyz')); d['rel'] = rng.choice(['at least','less than']); d['N'] = rng.choice([5,8,10,15,20])
    return d
def build(tasks, plan, combos, rng):
    items = []; ti = iter(tasks)
    for k, cnt in plan:
        for _ in range(cnt):
            t = next(ti); inst = rand_inst(k, rng, t); inst['text'] = inst_text(inst, rng)
            items.append({'task': t, 'insts': [inst]})
    for _ in range(combos):
        t = next(ti); ks = rng.sample(['lowercase','no_comma','capword','words','sentences','paragraphs','keyword','highlight'], 2)
        if 'lowercase' in ks and 'capword' in ks: ks = ['lowercase','words']
        insts = [rand_inst(k, rng, t) for k in ks]
        for i in insts: i['text'] = inst_text(i, rng)
        items.append({'task': t, 'insts': insts})
    for it in items:
        it['prompt'] = it['task'] + ' ' + ' '.join(i['text'] for i in it['insts'])
    return items
choice_tasks, confirm_tasks = pool[:600], pool[600:]
plan1 = [('lowercase',64),('no_comma',64),('capword',56),('capital',24),('words',48),('sentences',32),('paragraphs',40),
         ('repeat',48),('keyword',32),('highlight',24),('letter',16)]
P1 = build(choice_tasks, plan1, 64, R)
print(len(P1)); json.dump(P1, open('/work/p1_meta.json','w')); json.dump([x['prompt'] for x in P1], open('/work/p1_prompts.json','w'))
for x in P1[::90]: print(x['prompt'][:250])
```

The rendering matches. Now the texts for teacher-forced pass 2, all with the starting edit's own generations (prompt + thinking + answer, at most 4,000 tokens):
- answers to lowercase prompts, no-comma prompts and all-caps prompts (positives for each constraint);
- answers to other instruction prompts without case or comma constraints (controls);
- 25 MBPP prompts with their reference solution as an answer after an empty thinking, as code negatives. A gate that suppressed commas in code would be disastrous, so I need code positions to test against.

I'll ask for token log-probs, top-20 next-token distributions, and hidden states at indices 12, 22 and 24. Index 22 is the input of the layer-22 MLP, a candidate place for a gated neuron; 24 is the final residual, needed to calibrate logit effects. This block builds the set and checks the memory.

