tf2_meta = [(k, idx) for k in ['LC','NC','CAP','CTRL'] for idx, _ in sel[k]] + [('CODE', i) for i in range(25)]
tf2_texts = [full_text(P1[idx]['prompt'], G1[idx]['text']) for k, idx in tf2_meta[:-25]] + code_texts
lens = [len(tok(t)['input_ids']) for t in tf2_texts]
print(len(tf2_texts), 'max len', max(lens), 'total', sum(lens), 'hidden GB', len(tf2_texts)*3*max(lens)*1024*2/1e9)
