Regions are located. First analysis: does the comma probability in no-comma answers drift upward as the answer grows? I'll compare the mean probability on comma tokens per answer-position bin in no-comma answers (NC) with that in control answers (CTRL), and also split NC into compliant and violating answers.

```python
# Hypothesis: in NC answers comma prob is suppressed vs CTRL, but the suppression weakens with answer position (drift).
def ans_positions(i):
    p_end, a0, n = reg2[i]; return np.arange(a0 - 1, n - 1)   # distributions predicting answer tokens a0..n-1
bins = [0, 16, 32, 64, 128, 256, 512, 4000]
def by_pos(groups, arr, sel_fn=None):
    out = {}
    for gname in groups:
        idxs = np.where(grp2 == gname)[0] if sel_fn is None else [i for i in np.where(grp2 == gname)[0] if sel_fn(i)]
        vals = defaultdict(list)
        for i in idxs:
            ps = ans_positions(i); a0 = reg2[i][1]
            for t in ps:
                k = np.searchsorted(bins, t - a0 + 1, side='right') - 1; vals[k].append(arr[i, t])
        out[gname] = [ (np.mean(vals[k]) if vals[k] else np.nan, len(vals[k])) for k in range(len(bins)-1)]
    return out
viol_nc = {i: (',' in tok.decode(toks2[i][reg2[i][1]:reg2[i][2]])) for i in np.where(grp2 == 'NC')[0]}
res = by_pos(['CTRL','NC','CODE'], pc2)
res_v = by_pos(['NC'], pc2, lambda i: viol_nc[i]); res_c = by_pos(['NC'], pc2, lambda i: not viol_nc[i])
print('bins', bins)
for name, rr in [('CTRL', res['CTRL']), ('NC all', res['NC']), ('NC violating', res_v['NC']), ('NC compliant', res_c['NC']), ('CODE', res['CODE'])]:
